 let unavailableBasis=new Set();
 let snapshot=null,plan=null,quantities=new Map(),added=new Set(),dirty=false,step=0,sourceData=null,cartons=[],packageChoices=[],poll=null,busy=false,sourceSelections=new Map(),inboundView=null,selectedWarehouse=null,selectedChild=null,transportByOrigin={},preparationByOrigin={},selectedOptions=new Map();
 const editor=$('#fba-plan-editor'),wizard=$('#fba-plan-workflow');
 const invalidEdits=new Map();
 let editorSave=null;
 const conditionPicker=$('[data-fba-condition]'),conditionKey=document.body.dataset.fbaPreferenceScope&&document.body.dataset.fbaConnection?['nextai:fba-condition:v1',document.body.dataset.fbaPreferenceScope,document.body.dataset.fbaConnection].join(':'):null;
 let condition='NEW';try{const saved=conditionKey?localStorage.getItem(conditionKey):null;if(conditionPicker&&[...conditionPicker.options].some(o=>o.value===saved))condition=saved;}catch{}if(conditionPicker){conditionPicker.value=condition;conditionPicker.dispatchEvent(new Event('platform-choice-sync'));}

 async function api(path,body){const headers={Accept:'application/json'};if(body!==undefined){headers['Content-Type']='application/json';headers[$('meta[name=_csrf_header]').content]=$('meta[name=_csrf]').content;}const response=await fetch(path.startsWith('/app/')?path:base+path,{method:body===undefined?'GET':'POST',headers,body:body===undefined?undefined:JSON.stringify(body),cache:'no-store',signal:AbortSignal.timeout(20000)});const value=await response.json().catch(()=>{throw Error('Your session ended. Sign in and retry; saved work is retained.');});if(!response.ok){const error=Error(value.error||value.detail||value.message||'Could not complete this action.');error.status=response.status;throw error;}return value;}
 const lines=()=>[...quantities].filter(([,n])=>n>0).map(([sku,units])=>({sku,units}));
 const num=n=>n==null?'—':Number(n).toLocaleString(undefined,{maximumFractionDigits:2});
 document.addEventListener('fba-inventory-refreshed',()=>safely(async()=>{await api('/forecast',{});await forecast();}));
 const status=message=>{$('[data-forecast-status]').textContent=message;};
 function identity(){ $('[data-plan-title]').textContent=plan?.name||'Current suggestion';$('[data-plan-status]').textContent=plan?`${plan.status.replaceAll('_',' ')}${dirty?' · changes not saved':''} · ${plan.status==='DRAFT'?'no stock reserved':'source allocation retained'}`:'Not saved';}
 function record(r){return `<td data-column="record-context" class="table-context-cell table-overview-cell"><div class="table-overview-layout"><span class="table-overview-picture product-thumbnail-slot">${r.image&&/^https?:\/\//.test(r.image)?`<img src="${esc(r.image)}" alt="" loading="lazy">`:`<b>${esc(r.sku.slice(0,2))}</b>`}</span><div class="table-overview-rail"><button class="collaboration-row-button" type="button" data-fba-chat data-entity-type="MARKETPLACE_SKU" data-entity-id="${esc(r.sku)}" data-title="${esc(r.title)}" data-can-collaborate="${editable}" data-parent-url="/app/inventory/fba-replenishment" aria-label="Collaboration for ${esc(r.sku)}"></button></div></div></td>`;}
 function parts(sku){if(unavailableBasis.has(sku))return [];return sourceData?.components?.filter(c=>c.sku===sku).length?sourceData.components.filter(c=>c.sku===sku):(snapshot?.rows.find(r=>r.sku===sku)?.components||[]);}
 function caseText(components,units){const v=window.NextAiFbaPlanning.caseQuantity(components,units);return v?`${num(v.cases)} cases + ${num(v.each)} each`:null;}
 function componentNotes(components,units){if(units==null)return '';const v=caseText(components,units);if(v)return `<small>${v} · ${num(window.NextAiFbaPlanning.caseBasis(components).masterCase)}/case</small>`;return (components||[]).map(c=>`<small>${esc(c.name||c.itemCode||'Mapped product')}: ${caseText([c],units)||num(units*(c.each??c.quantity))+' each · case size unavailable'}</small>`).join('');}
 function quantityInput(sku,units,attribute,disabled=false,components=parts(sku),unitLabel='SKU units'){const invalid=attribute==='data-quantity'?invalidEdits.get(sku):null;if(invalid?.value!=null)units=invalid.value===''?null:Number(invalid.value);const v=window.NextAiFbaPlanning.caseQuantity(components,units??0),key=esc(sku),d=disabled?'disabled':'';if(!v)return `<input class="fba-plan-quantity" ${attribute}="${key}" type="number" min="0" max="1000000" step="1" value="${units??''}" aria-label="${esc(unitLabel)} for ${key}" ${d}><small>${esc(unitLabel)}${components.length>1?' · mixed products':' · case size unavailable'}</small>${componentNotes(components,units)}`;return `<div class="fba-case-input" data-case-sku="${key}" data-case-unit="${esc(unitLabel)}"><label>Cases<input type="number" min="0" max="1000000" step="1" data-case-cases aria-label="${unitLabel==='Product each'?'Product cases for ':'Cases for '}${key}" value="${invalid?.caseValues?.[0]??(units==null?'':v.cases)}" ${d}></label><label>Each<input type="number" min="0" max="1000000000" step="1" data-case-each aria-label="${unitLabel==='Product each'?'Product each remainder for ':'Each remainder for '}${key}" value="${invalid?.caseValues?.[1]??(units==null?'':v.each)}" ${d}></label><input type="hidden" ${attribute}="${key}" value="${units??''}" aria-label="${esc(unitLabel)} for ${key}" data-case-canonical><small data-case-total>${units==null?'':num(units)} ${esc(unitLabel)} · ${num(v.masterCase)} each/case</small><small class="fba-quantity-validation" data-case-error role="alert"></small></div>`;}
 function readCaseInput(group){const inputs=[$('[data-case-cases]',group),$('[data-case-each]',group)],target=$('[data-case-canonical]',group),error=$('[data-case-error]',group);try{inputs.forEach(i=>i.setCustomValidity(''));if(inputs.some(i=>i.value===''||!i.checkValidity()))throw Error('Enter nonnegative whole cases and eaches.');const components=group.dataset.caseComponent!=null?[{...sourceData.components[+group.dataset.caseComponent],quantity:1}]:parts(group.dataset.caseSku);const units=window.NextAiFbaPlanning.skuQuantity(components,+inputs[0].value,+inputs[1].value);target.value=units;inputs.forEach(i=>i.setCustomValidity(''));error.textContent='';$('[data-case-total]',group).textContent=num(units)+' '+(group.dataset.caseUnit||'SKU units')+' · '+num(window.NextAiFbaPlanning.caseBasis(components).masterCase)+' each/case';target.dispatchEvent(new Event('input',{bubbles:true}));return units;}catch(e){inputs[0].setCustomValidity(e.message);error.textContent=e.message;if(target.matches('[data-quantity]'))invalidEdits.set(target.dataset.quantity,{value:target.value,error:e.message,caseValues:inputs.map(i=>i.value)});return null;}}
 function recommendedCases(components,units){const v=window.NextAiFbaPlanning.caseQuantity(components,units);return v?num(v.cases+(v.each>0?1:0))+' cases':null;}
 function stockLevel(r){const v=window.NextAiFbaPlanning.coverage(r),names={available:'Available',inbound:'Inbound',transfer:'FC transfer'},tooltip=v.buckets.map(b=>names[b.key]+' '+num(b.units)+' SKU units'+(b.days==null?' · coverage unknown':' ('+num(b.days)+' days)')).join(' · ')+'. Inbound and FC transfer are not available yet; arrival is not confirmed.';return `<strong class="rp-stock-label" data-tone="${v.tone}">${v.label}</strong><small class="rp-cover">${v.days==null?'Coverage unknown':num(v.days)+' days left'}</small><div class="rp-stock-track" data-tone="${v.tone}" role="img" tabindex="0" aria-label="${esc(tooltip)}" data-tooltip="${esc(tooltip)}"><div class="fba-coverage-segments">${v.buckets.map(b=>`<span data-coverage-bucket="${b.key}" style="width:${b.width}%"></span>`).join('')}</div><i style="left:${v.lowPosition}%"></i><i style="left:${v.targetPosition}%"></i><i style="left:${v.overstockPosition}%"></i></div><div class="rp-level-labels fba-level-labels"><span data-marker-position="${v.lowPosition}" style="left:${v.lowPosition}%">Low ${v.low}</span><span data-marker-position="${v.targetPosition}" style="left:${v.targetPosition}%">Target ${v.target}</span><span data-marker-position="${v.overstockPosition}" style="left:${v.overstockPosition}%">Over ${v.overstock}</span></div><small class="fba-stockout-date">${r.recommendation.stockout?'Stockout '+esc(r.recommendation.stockout):v.tone==='unknown'?'Review planning evidence':'No projected stockout'}</small><small class="fba-daily-demand">${num(r.recommendation.daily)} SKU units/day</small>`;}
 function layoutCoverageLabels(){const layouts=$$('.fba-level-labels').map(group=>{const width=group.clientWidth,labels=[...group.children],sizes=labels.map(label=>label.getBoundingClientRect()),lineHeight=Math.max(14,...sizes.map(b=>b.height)),rows=[],positions=[];for(let i=0;i<labels.length;i++){const size=sizes[i].width,marker=width*Number(labels[i].dataset.markerPosition)/100,preferred=Math.max(0,Math.min(width-size,marker-size/2));let placement=null;for(let row=0;!placement;row++){rows[row]||=[];const candidates=[preferred];for(const start of candidates)if(!rows[row].some(v=>start<v.end+6&&start+size>v.start-6)){placement={row,start,end:start+size};break;}}rows[placement.row].push(placement);positions.push(placement);}return{group,labels,positions,step:lineHeight+3,height:Math.max(17,(rows.length-1)*(lineHeight+3)+lineHeight)};});for(const v of layouts){v.group.style.height=v.height+'px';v.labels.forEach((label,i)=>{label.style.left=v.positions[i].start+'px';label.style.top=v.positions[i].row*v.step+'px';label.style.transform='none';});}}
 function fbaStock(r){const html=window.NextAiFbaStock.html(r.sku,r.amazon),button=html.match(/<button\b[^>]*class="fba-stock-trigger"[\s\S]*?<\/button>/)?.[0];return button?html.replace(button,'').replace(/(<div\b[^>]*class="fba-stock"[^>]*>)/,'$1'+button):html;}
 function product(r){const domain=document.body.dataset.amazonDomain,skuUrl='https://sellercentral.'+domain+'/myinventory/inventory?searchTerm='+encodeURIComponent(r.sku);return `<button type="button" class="sku-movements-trigger fba-plan-description" data-movement-sku="${esc(r.sku)}" data-movement-fba="true" data-movement-account="${esc(document.body.dataset.fbaAccount)}" data-movement-store="${esc(document.body.dataset.fbaConnection)}">${esc(r.title)}</button><div class="sku-identifier-line"><a class="sku-identifier-icon" href="${esc(skuUrl)}" target="_blank" rel="noopener"><img src="/images/platform/table/seller-central.png" alt="Open SKU in Seller Central"></a><button type="button" class="sku-copy-value" data-ui-copy="${esc(r.sku)}">${esc(r.sku)}</button><button type="button" class="sku-filter-lock" data-fba-filter="${esc(r.sku)}" aria-label="Filter by SKU"><img src="/images/platform/05-unlocked.svg" alt=""></button></div>${r.asin?`<div class="sku-identifier-line"><a class="sku-identifier-icon" href="https://www.${esc(domain)}/dp/${encodeURIComponent(r.asin)}" target="_blank" rel="noopener"><img src="/images/platform/table/amazon.com-logo.png" alt="Open Amazon product"></a><button type="button" class="sku-copy-value" data-ui-copy="${esc(r.asin)}">${esc(r.asin)}</button><button type="button" class="sku-filter-lock" data-fba-filter="${esc(r.asin)}" aria-label="Filter by ASIN"><img src="/images/platform/05-unlocked.svg" alt=""></button></div>`:''}<div class="sku-identifier-line sku-approved-mapping"><button type="button" class="sku-mapping-icon" data-fba-mapping data-seller-sku="${esc(r.sku)}" data-product-title="${esc(r.title)}" data-image="${esc(r.image)}" data-can-edit="${editable}" aria-label="Review SKU mapping"><img src="/images/platform/optimized32/sku-mapped.png" alt=""></button>${r.components.map(c=>`<span class="sku-identifier-line"><button type="button" class="sku-copy-value" data-ui-copy="${esc(c.itemCode||'')}" aria-label="Item code ${esc(c.itemCode||'unavailable')}">${esc(c.itemCode||'Item code unavailable')} × ${num(c.each)}</button>${c.itemCode?`<button type="button" class="sku-filter-lock" data-fba-filter="${esc(c.itemCode)}" aria-label="Filter by item code"><img src="/images/platform/05-unlocked.svg" alt=""></button>`:''}</span>`).join('')||'<span>Needs mapping</span>'}</div>`;}
 function basis(r){const x=r.recommendation,a=r.amazon||{},facts=[['Daily demand',num(x.daily)+' SKU units/day'],['Amazon available',num(a.available)+' SKU units'],['Target',r.policy.targetDays+' days at arrival'],['Arrival',r.policy.leadTimesConfirmed?window.NextAiFbaExplanation.date(x.arrival):'Lead time needed'],['30 / 90-day shipped sales',num(r.demand?.units30)+' / '+num(r.demand?.units90)+' SKU units'],['Verified selling days',num(r.demand?.verifiedSellingDays30)+' / '+num(r.demand?.verifiedSellingDays90)],['Inventory checked',a.observedAt?new Date(a.observedAt).toLocaleString():'Not imported']],events=window.NextAiFbaExplanation.events(r,snapshot,document.body.dataset.forecastTimeZone),groups=new Map();for(const e of events.rows){const key=e.reason;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(e);}
  const warnings=[...new Set([...x.warnings,...r.blockers])].filter(w=>!w.startsWith('Set and confirm arrival lead times.'));
  return `<p class="fba-basis-sku">${esc(r.sku)}</p><p class="fba-basis-lead">${x.recommended==null?'Suggestion unavailable':'Suggested '+num(x.recommended)+' SKU units'}</p><p>${r.policy.dailyOverride!=null?'Cover the target period using your daily demand estimate and available Amazon stock.':'Based on eligible shipped SKU units; pending and cancelled orders are excluded.'}</p>${!r.policy.leadTimesConfirmed?'<p class="fba-basis-warning">Add warehouse-to-Amazon lead times to estimate arrival and stock needs. Suggested quantity may change.</p>':''}<dl class="fba-basis-facts">${facts.map(([label,value])=>`<div><dt>${esc(label)}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl>${warnings.length?`<ul class="fba-basis-warnings">${warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul>`:''}<h3>Special events</h3>${events.unknown?'<p>Planning dates need review.</p>':!events.rows.length?'<p>No relevant events in this planning window.</p>':[...groups].map(([reason,rows])=>`<section class="fba-event-summary"><p>${rows[0].used?'Applied':'Not applied'} · ${esc(reason)}</p><ul>${rows.map(e=>`<li><strong>${esc(e.name)}</strong> · ${window.NextAiFbaExplanation.date(e.start)}${e.end!==e.start?' – '+window.NextAiFbaExplanation.date(e.end):''}${e.used?' · '+num(e.uplift*100)+'% uplift':''}${e.units>0||e.baselineUnits>0?`<small>Prior ${num(e.units)} units · baseline ${num(e.baselineUnits)} · availability ${num(e.availabilityCoverage*100)}%</small>`:''}</li>`).join('')}</ul></section>`).join('')}<h3>Mapped products</h3>${r.components.map(c=>`<p>${esc(c.name)} × ${c.each} · ${num(c.warehouse)} each available</p>`).join('')||'<p>Mapping needs review.</p>'}`;
 }
 function emptyRecommendations(query){
  if(query)return 'No SKUs match this search.';
  const candidates=window.NextAiFbaPlanning.visible(snapshot.rows,condition,''),unknown=candidates.filter(r=>r.recommendation.recommended==null);
  if(!candidates.length)return 'No SKUs match this condition.';
  const times=candidates.map(r=>r.amazon?.observedAt).filter(Boolean).map(t=>new Date(t).getTime()).filter(Number.isFinite),dates=[...new Set(times)].sort((a,b)=>a-b);
  const source=dates.length?`<small>${dates.length===1?'Last Amazon inventory: ':'Amazon inventory observations: '}${esc(new Date(dates[0]).toLocaleString())}${dates.length>1?' – '+esc(new Date(dates.at(-1)).toLocaleString()):''}</small>`:'<small>Amazon inventory observations are not available.</small>';
  const reason=unknown.every(r=>r.recommendation.status==='Inventory needs review')?'Amazon inventory needs refreshing':'review inventory and planning evidence';
  return `<strong>${unknown.length?'Recommendations unavailable for '+unknown.length+' SKUs — '+reason+'.':'No positive recommendations for the evaluated SKUs.'}</strong>${source}${unknown.length?`<button type="button" class="rp-text-button" data-basis="${esc(unknown[0].sku)}" aria-label="Review inventory evidence for ${esc(unknown[0].sku)}">Review inventory evidence</button>`:''}<small>Search or add an item to enter your own quantity.</small>`;
 }
 function skuSettingsAction(row){if(!manager)return;const panel=$('.table-overview-rail .table-warning-panel',row);if(!panel||panel.querySelector('[data-fba-sku-settings]'))return;const button=document.createElement('button');button.type='button';button.className='table-action-entry';button.dataset.fbaSkuSettings=row.dataset.sku;button.setAttribute('aria-label','Replenishment settings for '+row.dataset.sku);const art=document.createElement('span');art.className='table-action-icon';art.setAttribute('aria-hidden','true');if(window.NextAiIcons)art.append(window.NextAiIcons.create('action:settings'));const label=document.createElement('span');label.className='table-action-label';const name=document.createElement('strong');name.textContent='Replenishment settings';const description=document.createElement('small');description.textContent='Low, Target and Overstock days';label.append(name,description);button.append(art,label);button.onclick=()=>{panel.closest('details').open=false;safely(()=>settings(false,row.dataset.sku));};panel.querySelector('.table-action-heading strong').textContent='Actions';panel.querySelector('.table-action-heading small')?.remove();panel.querySelector('.table-action-heading').after(button);}
 function warehouseDetails(row){const details=window.NextAiFbaPlanning.warehouseCapacity(row,snapshot.context?.warehouses||[]);return details?.length>1?details.map(w=>`<small>${esc([w.postal,w.name].filter(Boolean).join(' · '))} ${num(w.units)}</small>`).join(''):'';}
 function sales(row){const p=snapshot.context?.performance?.[row.sku];if(!p)return '<td data-column="four-week-sales"><small>Unavailable</small></td>';return `<td data-column="four-week-sales" data-refund-sku="${esc(row.sku)}" data-sku-refunds="${esc(p.refunds||'[]')}"><span class="weekly-sold-totals">${num(p.totals?.orders)} / ${num(p.totals?.units)} <small>Orders / Units</small></span><strong class="weekly-sales">${esc(p.weeks)}</strong></td>`;}
 function render(){if(!snapshot)return;const q=($('[data-supply-view]').hidden?$('[data-search]').value:$('[data-supply-search]').value).toLowerCase();const saved=new Map((plan?.checkpoint.lines||[]).map(l=>[l.sku,l.units]));
  const shown=window.NextAiFbaPlanning.displayed(snapshot.rows,condition,q,quantities,!!plan,added);
  $('[data-recommendations]').innerHTML=shown.map(r=>`<tr data-recommended="${r.recommendation.recommended>0}" data-sku="${esc(r.sku)}" data-entity-type="MARKETPLACE_SKU" data-entity-id="${esc(r.sku)}" data-title="${esc(r.title)}" data-can-collaborate="${editable}">${record(r)}<td data-column="product-sku"><div class="sku-workspace">${product(r)}</div></td><td data-column="stockout">${stockLevel(r)}</td><td class="numeric" data-column="recommended"><strong>${recommendedCases(r.components,r.recommendation.recommended)||num(r.recommendation.recommended)}</strong><button type="button" class="fba-basis-info" data-basis="${esc(r.sku)}" aria-label="Why this quantity for ${esc(r.sku)}" title="${r.policy.leadTimesConfirmed?'Why this quantity?':'Lead times need confirmation'}"><span aria-hidden="true">i</span></button><small>${r.recommendation.recommended==null?'Review planning evidence':num(r.recommendation.recommended)+' SKU units'}</small></td><td data-column="fba-stock">${fbaStock(r)}</td><td class="numeric" data-column="warehouse" data-warehouse-available>${caseText(r.components,r.warehouse)||num(r.warehouse)}<small>${num(r.warehouse)} SKU units</small>${warehouseDetails(r)}</td><td class="numeric" data-column="to-ship">${quantityInput(r.sku,quantities.get(r.sku),'data-quantity',!editable||plan&&plan.status!=='DRAFT',r.components)}<small>${plan&&saved.get(r.sku)!==quantities.get(r.sku)?'Edited':'SKU units'}</small><small data-quantity-error role="alert">${esc(invalidEdits.get(r.sku)?.error||'')}</small></td>${sales(r)}</tr>`).join('')||`<tr><td colspan="8" class="fba-empty-note">${emptyRecommendations(q)}</td></tr>`;
  $('[data-supply]').innerHTML=snapshot.supply.filter(r=>r.name.toLowerCase().includes(q)).map(r=>`<tr data-account-item="${esc(r.item)}"><td data-column="record-context" class="table-context-cell table-overview-cell"><span class="table-overview-picture"><b>${esc(r.name.slice(0,2))}</b></span></td><td><strong class="fba-supply-title">${esc(r.name)}</strong><details><summary>Supply basis</summary>${r.warnings.map(w=>`<p>${esc(w)}</p>`).join('')}${(r.channels||[]).map(c=>`<p>${esc(c.channel)+' · '+esc(c.sku)+' · '+num(c.daily)+' each/day · shortfall '+num(c.shortage)}</p>`).join('')}</details></td><td class="numeric">${num(r.daily)}</td><td class="numeric" data-column="warehouse" data-warehouse-available>${num(r.warehouse)}</td><td class="numeric">${num(r.amazon)}</td><td class="numeric">${num(r.shortfall)}</td></tr>`).join('');
  identity();const recommendationTable=$('[data-recommendation-count]');if(recommendationTable)recommendationTable.dataset.recommendationContext=conditionPicker?.selectedOptions?.[0]?.textContent||condition;$$('table[data-table-widget]').forEach(t=>{if(snapshot.generatedAt)t.dataset.salesAsOf=snapshot.generatedAt;t.dispatchEvent(new Event('table:rows-replaced'));});window.NextAiTableWidget?.refresh();$$('[data-recommendations] tr[data-sku]').forEach(row=>{window.prepareRecordSuggestionActions?.(row,$('.table-overview-rail',row));skuSettingsAction(row);});window.NextAiTableComposition?.prepare?.($('table[data-table-widget]'));layoutCoverageLabels();window.requestAnimationFrame?.(layoutCoverageLabels);
 }
 // Hydrate new evidence while preserving the user's quantities, added rows and table preferences.
 async function forecast(initial=false){try{const data=await api('/forecast');if(data.snapshot){
  document.body.dataset.forecastPending='false';const changed=!snapshot||snapshot.generatedAt!==data.snapshot.generatedAt||snapshot.formatVersion!==data.snapshot.formatVersion;
  if(changed||initial){const previous=snapshot,fresh=data.snapshot;
   if(previous&&!initial){const current=new Map(fresh.rows.map(r=>[r.sku,r]));fresh.rows=[...previous.rows.filter(r=>current.has(r.sku)).map(r=>current.get(r.sku)),...fresh.rows.filter(r=>!previous.rows.some(old=>old.sku===r.sku))];}
   snapshot=fresh;if(!plan&&!dirty)quantities=new Map(snapshot.rows.map(r=>[r.sku,window.NextAiFbaPlanning.initialQuantity(r)]));
   const focused=document.activeElement?.dataset?.quantity,open=[...document.querySelectorAll('details[open]')].map(d=>d.closest('[data-sku]')?.dataset.sku).filter(Boolean),x=window.scrollX,y=window.scrollY;
   render();for(const sku of open){const row=$$('[data-sku]').find(r=>r.dataset.sku===sku);row?.querySelector('details')?.setAttribute('open','');}if(focused)$$('[data-quantity]').find(i=>i.dataset.quantity===focused)?.focus({preventScroll:true});window.scrollTo(x,y);
  }
  status(`${data.refreshing?'Refreshing · ':''}Prepared ${new Date(data.snapshot.generatedAt).toLocaleString()}${data.error?' · '+data.error:''}`);
 }else{status(data.error||'Preparing recommendations…');if(data.error)$('[data-recommendations]').innerHTML='<tr><td colspan="8" class="fba-empty-note">'+esc(data.error)+'</td></tr>';}if(data.refreshing||!data.snapshot&&!data.error){clearTimeout(poll);poll=setTimeout(()=>forecast(!snapshot),3000);}}catch(e){status(e.message);}}

